/* ==========================================================================
   Crumb & Co. — Stylesheet for Home, Menu & Cakes
   Pure CSS (no frameworks). Matches hand-drawn paper prototypes.
   ========================================================================== */

:root {
  --bg-page: #fbf7f1;
  --bg-surface: #fffdf9;
  --bg-tint: #f3eadf;
  --bg-accent-soft: #f7e4e2;
  --ink-primary: #2d1c12;
  --ink-secondary: #5c4333;
  --ink-muted: #7e6556;
  --border-dark: #3b2416;
  --border-soft: #d9cbbd;
  --accent-brown: #5b3722;
  --accent-brown-hover: #442817;
  --accent-caramel: #c88d55;
  --accent-berry: #d87b86;
  --toast-bg: #fffdf9;
  --toast-border: #3b2416;
  --success-green: #2c6e49;
  --shadow-card: 0 3px 0 rgba(59, 36, 22, 0.12);
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-arch: 999px 999px 14px 14px;
  --max-width: 1080px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-family: "Georgia", "Times New Roman", serif;
  color: var(--ink-primary);
  background-color: var(--bg-page);
  line-height: 1.5;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input {
  font-family: inherit;
}

img,
svg {
  display: block;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 20px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* ==========================================================================
   Header & Navigation
   ========================================================================== */

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background-color: var(--bg-surface);
  border-bottom: 2px solid var(--border-dark);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 68px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: var(--ink-primary);
  flex-shrink: 0;
}

.brand-icon {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-links a {
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.98rem;
  font-weight: 600;
  color: var(--ink-secondary);
  padding: 6px 2px;
  border-bottom: 2px solid transparent;
  transition: color 0.15s ease, border-color 0.15s ease;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--ink-primary);
  border-bottom-color: var(--border-dark);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-shrink: 0;
}

.icon-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border: 1.5px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink-primary);
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.icon-btn:hover {
  background-color: var(--bg-tint);
  border-color: var(--border-soft);
}

.icon-btn svg {
  width: 22px;
  height: 22px;
}

.cart-badge {
  position: absolute;
  top: -4px;
  right: -5px;
  min-width: 19px;
  height: 19px;
  padding: 0 5px;
  border-radius: 999px;
  background-color: var(--accent-brown);
  color: #fff;
  border: 1.5px solid var(--bg-surface);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  line-height: 16px;
  text-align: center;
}

.cart-badge.is-empty {
  display: none;
}

.menu-toggle {
  display: none;
}

.mobile-nav {
  display: none;
  border-top: 1px solid var(--border-soft);
  background-color: var(--bg-surface);
  padding: 12px 20px 16px;
}

.mobile-nav.is-open {
  display: block;
}

.mobile-nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.mobile-nav-list a {
  display: block;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-weight: 600;
  color: var(--ink-secondary);
}

.mobile-nav-list a:hover,
.mobile-nav-list a.active {
  background-color: var(--bg-tint);
  color: var(--ink-primary);
}

/* ==========================================================================
   Shared Main Layout & Footer
   ========================================================================== */

main {
  flex: 1;
  padding: 28px 0 48px;
}

.site-footer {
  border-top: 2px solid var(--border-dark);
  background-color: var(--bg-surface);
  padding: 16px 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.9rem;
  color: var(--ink-secondary);
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: flex-start;
}

/* ==========================================================================
   Buttons
   ========================================================================== */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 22px;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: 2px solid var(--border-dark);
  cursor: pointer;
  transition: transform 0.1s ease, background-color 0.15s ease, color 0.15s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: var(--accent-brown);
  color: #fff;
}

.btn-primary:hover {
  background-color: var(--accent-brown-hover);
}

.btn-secondary {
  background-color: var(--bg-surface);
  color: var(--ink-primary);
}

.btn-secondary:hover {
  background-color: var(--bg-tint);
}

/* ==========================================================================
   Webpage 1 — Home Page
   ========================================================================== */

.hero-box {
  background: linear-gradient(135deg, var(--bg-surface) 0%, var(--bg-tint) 100%);
  border: 2px solid var(--border-dark);
  border-radius: var(--radius-md);
  padding: 36px 34px;
  box-shadow: var(--shadow-card);
  margin-bottom: 34px;
}

.hero-title {
  margin: 0 0 8px;
  font-size: clamp(1.75rem, 3.4vw, 2.5rem);
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink-primary);
}

.hero-subtitle {
  margin: 0 0 24px;
  max-width: 520px;
  font-size: 1.08rem;
  color: var(--ink-secondary);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.section-block {
  margin-bottom: 36px;
}

.section-heading {
  margin: 0 0 18px;
  font-size: 1.45rem;
  font-weight: 700;
  color: var(--ink-primary);
}

/* Arched cards matching Webpage 1 Desktop prototype */
.arch-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.arch-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  text-align: center;
  background-color: var(--bg-surface);
  border: 2px solid var(--border-dark);
  border-radius: var(--radius-arch);
  padding: 26px 16px 18px;
  min-height: 195px;
  box-shadow: var(--shadow-card);
  transition: transform 0.15s ease, background-color 0.15s ease;
}

.arch-card:hover {
  transform: translateY(-3px);
  background-color: var(--bg-tint);
}

.arch-card-art {
  width: 78px;
  height: 78px;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.arch-card-art svg {
  width: 100%;
  height: 100%;
}

.arch-card-text {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.arch-card-title {
  margin: 0;
  font-size: 1.08rem;
  font-weight: 700;
  color: var(--ink-primary);
}

.arch-card-meta {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.84rem;
  color: var(--ink-muted);
}

.bestseller-card {
  min-height: 185px;
  padding: 24px 14px 16px;
}

.bestseller-price {
  margin-top: 4px;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--accent-brown);
}

/* ==========================================================================
   Webpage 2 — Menu Page
   ========================================================================== */

.page-title {
  margin: 0 0 18px;
  font-size: clamp(1.75rem, 3vw, 2.25rem);
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.menu-search-wrap {
  position: relative;
  margin-bottom: 16px;
}

.menu-search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  color: var(--ink-muted);
  pointer-events: none;
}

.menu-search-input {
  width: 100%;
  padding: 12px 16px 12px 44px;
  font-size: 1rem;
  color: var(--ink-primary);
  background-color: var(--bg-surface);
  border: 2px solid var(--border-dark);
  border-radius: var(--radius-sm);
  outline: none;
}

.menu-search-input:focus {
  background-color: #fff;
  box-shadow: 0 0 0 3px rgba(200, 141, 85, 0.25);
}

.filter-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 22px;
}

.filter-tab {
  padding: 7px 18px;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink-primary);
  background-color: var(--bg-surface);
  border: 2px solid var(--border-dark);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.filter-tab:hover {
  background-color: var(--bg-tint);
}

.filter-tab.is-active {
  background-color: var(--accent-brown);
  color: #fff;
}

.menu-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.menu-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 18px;
  background-color: var(--bg-surface);
  border: 2px solid var(--border-dark);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-card);
}

.menu-row[hidden] {
  display: none;
}

.menu-row-left {
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: 0;
}

.menu-thumb {
  width: 58px;
  height: 58px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--bg-tint);
  border: 1.5px solid var(--border-dark);
  border-radius: var(--radius-sm);
  padding: 6px;
}

.menu-thumb svg {
  width: 100%;
  height: 100%;
}

.menu-info {
  min-width: 0;
}

.menu-item-name {
  margin: 0 0 3px;
  font-size: 1.18rem;
  font-weight: 700;
  color: var(--ink-primary);
}

.menu-item-desc {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.94rem;
  color: var(--ink-secondary);
}

.menu-add-btn {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.45rem;
  font-weight: 600;
  line-height: 1;
  color: var(--ink-primary);
  background-color: var(--bg-surface);
  border: 2px solid var(--border-dark);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.menu-add-btn:hover {
  background-color: var(--accent-brown);
  color: #fff;
}

.menu-empty {
  padding: 28px;
  text-align: center;
  background-color: var(--bg-surface);
  border: 2px dashed var(--border-soft);
  border-radius: var(--radius-sm);
  color: var(--ink-muted);
}

/* ==========================================================================
   Webpage 3 — Cakes Page (+ Vertical Prototype States 1 & 2)
   ========================================================================== */

.page-header-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
}

.page-header-row .page-title {
  margin: 0;
}

.back-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  font-size: 1.4rem;
  font-weight: 700;
  border: 2px solid var(--border-dark);
  border-radius: var(--radius-sm);
  background-color: var(--bg-surface);
  transition: background-color 0.15s ease;
}

.back-link:hover {
  background-color: var(--bg-tint);
}

.cakes-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}

.cake-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background-color: var(--bg-surface);
  border: 2px solid var(--border-dark);
  border-radius: var(--radius-sm);
  padding: 20px 18px 18px;
  box-shadow: var(--shadow-card);
  text-align: center;
}

.cake-card-top {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.cake-art {
  width: 86px;
  height: 86px;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cake-art svg {
  width: 100%;
  height: 100%;
}

.cake-name {
  margin: 0 0 6px;
  font-size: 1.12rem;
  font-weight: 700;
  color: var(--ink-primary);
}

.cake-price {
  margin: 0 0 14px;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.96rem;
  font-weight: 600;
  color: var(--ink-secondary);
}

.cake-price-label {
  display: none;
}

.add-cart-btn {
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 14px;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink-primary);
  background-color: var(--bg-surface);
  border: 2px solid var(--border-dark);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.add-cart-btn:hover {
  background-color: var(--accent-brown);
  color: #fff;
}

.add-cart-btn svg {
  width: 17px;
  height: 17px;
  flex-shrink: 0;
}

/* ==========================================================================
   Toast Notification (State 2 — Item Added)
   ========================================================================== */

.toast {
  position: fixed;
  right: 20px;
  bottom: 24px;
  z-index: 100;
  min-width: 260px;
  max-width: 340px;
  padding: 14px 16px;
  background-color: var(--toast-bg);
  border: 2px solid var(--toast-border);
  border-radius: var(--radius-sm);
  box-shadow: 0 6px 18px rgba(45, 28, 18, 0.22);
  opacity: 0;
  transform: translateY(12px);
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.toast.is-visible {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

.toast-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 4px;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--success-green);
}

.toast-message {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.9rem;
  color: var(--ink-primary);
}

/* ==========================================================================
   Responsive Breakpoints (Matches Mobile View & Vertical Prototype)
   ========================================================================== */

@media (max-width: 860px) {
  .arch-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cakes-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .nav-links,
  .header-search-btn {
    display: none;
  }

  .menu-toggle {
    display: inline-flex;
  }

  main {
    padding: 20px 0 36px;
  }

  .hero-box {
    padding: 22px 18px;
    margin-bottom: 26px;
  }

  .hero-actions {
    gap: 10px;
  }

  .hero-actions .btn {
    flex: 1 1 auto;
    padding: 10px 14px;
    font-size: 0.9rem;
  }

  /* Mobile View: Shop by Category becomes stacked horizontal icon-left cards */
  .category-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .category-grid .arch-card {
    flex-direction: row;
    justify-content: flex-start;
    text-align: left;
    min-height: auto;
    border-radius: var(--radius-sm);
    padding: 12px 14px;
    gap: 14px;
  }

  .category-grid .arch-card-art {
    width: 54px;
    height: 54px;
    margin-bottom: 0;
    padding: 6px;
    background-color: var(--bg-tint);
    border: 1.5px solid var(--border-dark);
    border-radius: var(--radius-sm);
    flex-shrink: 0;
  }

  /* Vertical Prototype State 1: Cakes page mobile stacked rows with divider */
  .cakes-grid {
    grid-template-columns: 1fr;
    gap: 0;
    background-color: var(--bg-surface);
    border: 2px solid var(--border-dark);
    border-radius: var(--radius-sm);
  }

  .cake-card {
    border: none;
    border-bottom: 2px solid var(--border-dark);
    border-radius: 0;
    box-shadow: none;
    text-align: left;
    padding: 18px 16px;
  }

  .cake-card:last-child {
    border-bottom: none;
  }

  .cake-card-top {
    flex-direction: row;
    align-items: center;
    gap: 14px;
    margin-bottom: 8px;
  }

  .cake-art {
    width: 66px;
    height: 66px;
    margin-bottom: 0;
    flex-shrink: 0;
  }

  .cake-name {
    font-size: 1.25rem;
    margin: 0;
  }

  .cake-price {
    margin: 0 0 12px;
    font-size: 1rem;
  }

  .cake-price-label {
    display: inline;
    font-weight: 400;
    color: var(--ink-muted);
    margin-right: 4px;
  }

  .menu-row {
    padding: 12px 14px;
    gap: 12px;
  }

  .menu-thumb {
    width: 50px;
    height: 50px;
  }

  .toast {
    left: 16px;
    right: 16px;
    bottom: 18px;
    max-width: none;
  }
}

/* ==========================================================================
   Crumb & Co. — Vanilla JavaScript for Home, Menu & Cakes
   ========================================================================== */

(function () {
  const CART_STORAGE_KEY = "crumbAndCoCart";

  function readCart() {
    try {
      const raw = localStorage.getItem(CART_STORAGE_KEY);
      const parsed = raw ? JSON.parse(raw) : [];
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  function saveCart(cart) {
    try {
      localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(cart));
    } catch {
      // Ignore storage errors in restricted browser contexts
    }
  }

  function updateCartBadge() {
    const badge = document.getElementById("cart-badge");
    if (!badge) return;

    const totalQty = readCart().reduce((sum, item) => sum + (item.quantity || 1), 0);
    badge.textContent = String(totalQty);
    badge.classList.toggle("is-empty", totalQty === 0);
  }

  let toastTimer = null;

  function showToast(itemName) {
    const toast = document.getElementById("cart-toast");
    const toastMessage = document.getElementById("toast-message");
    if (!toast || !toastMessage) return;

    toastMessage.textContent = `${itemName} was added to the cart.`;
    toast.classList.add("is-visible");

    if (toastTimer) {
      clearTimeout(toastTimer);
    }

    toastTimer = setTimeout(() => {
      toast.classList.remove("is-visible");
    }, 3000);
  }

  function addItemToCart(id, name, price) {
    const cart = readCart();
    const existing = cart.find((item) => item.id === id);

    if (existing) {
      existing.quantity = (existing.quantity || 1) + 1;
    } else {
      cart.push({
        id,
        name,
        price: Number(price),
        quantity: 1
      });
    }

    saveCart(cart);
    updateCartBadge();
    showToast(name);
  }

  function initAddToCartButtons() {
    const buttons = document.querySelectorAll("[data-add-to-cart]");
    buttons.forEach((button) => {
      button.addEventListener("click", () => {
        const id = button.getAttribute("data-id") || "";
        const name = button.getAttribute("data-name") || "Bakery Item";
        const price = button.getAttribute("data-price") || "0";
        addItemToCart(id, name, price);
      });
    });
  }

  function initMobileMenu() {
    const toggle = document.getElementById("menu-toggle");
    const mobileNav = document.getElementById("mobile-nav");
    if (!toggle || !mobileNav) return;

    toggle.addEventListener("click", () => {
      const isOpen = mobileNav.classList.toggle("is-open");
      toggle.setAttribute("aria-expanded", String(isOpen));
    });
  }

  function initHeaderSearchShortcut() {
    const headerSearchBtn = document.getElementById("header-search-btn");
    const menuSearchInput = document.getElementById("menu-search");
    if (!headerSearchBtn) return;

    headerSearchBtn.addEventListener("click", (event) => {
      if (menuSearchInput) {
        event.preventDefault();
        menuSearchInput.focus();
      }
    });
  }

  function initMenuFiltering() {
    const searchInput = document.getElementById("menu-search");
    const filterTabs = document.querySelectorAll("[data-filter]");
    const menuRows = document.querySelectorAll(".menu-row");
    const emptyState = document.getElementById("menu-empty");

    if (!searchInput || filterTabs.length === 0 || menuRows.length === 0) {
      return;
    }

    let activeCategory = "all";

    const params = new URLSearchParams(window.location.search);
    const initialCategory = (params.get("category") || "").toLowerCase();
    if (["all", "cakes", "pastries", "breads"].includes(initialCategory)) {
      activeCategory = initialCategory;
      filterTabs.forEach((tab) => {
        tab.classList.toggle("is-active", tab.getAttribute("data-filter") === activeCategory);
      });
    }

    function applyFilters() {
      const query = searchInput.value.trim().toLowerCase();
      let visibleCount = 0;

      menuRows.forEach((row) => {
        const rowCategory = (row.getAttribute("data-category") || "").toLowerCase();
        const searchText = (row.getAttribute("data-search") || row.textContent || "").toLowerCase();

        const matchesCategory = activeCategory === "all" || rowCategory === activeCategory;
        const matchesQuery = query === "" || searchText.includes(query);
        const shouldShow = matchesCategory && matchesQuery;

        row.hidden = !shouldShow;
        if (shouldShow) {
          visibleCount += 1;
        }
      });

      if (emptyState) {
        emptyState.hidden = visibleCount > 0;
      }
    }

    filterTabs.forEach((tab) => {
      tab.addEventListener("click", () => {
        activeCategory = tab.getAttribute("data-filter") || "all";
        filterTabs.forEach((btn) => {
          btn.classList.toggle("is-active", btn === tab);
        });
        applyFilters();
      });
    });

    searchInput.addEventListener("input", applyFilters);
    applyFilters();
  }

  document.addEventListener("DOMContentLoaded", () => {
    updateCartBadge();
    initMobileMenu();
    initHeaderSearchShortcut();
    initAddToCartButtons();
    initMenuFiltering();
  });
})();

