/* ==========================================================================
   Crumb & Co. — Artisan Bakery Stylesheet
   Pure CSS (no frameworks). Matches hand-drawn prototypes with patisserie polish.
   ========================================================================== */

:root {
  --bg-page: #faf6f0;
  --bg-surface: #ffffff;
  --bg-cream: #f4ece1;
  --bg-warm: #efe3d3;
  --ink-primary: #2a1911;
  --ink-secondary: #5c4234;
  --ink-muted: #846a5b;
  --accent-espresso: #3b2216;
  --accent-espresso-hover: #26140c;
  --accent-caramel: #b87a44;
  --accent-berry: #b84e5c;
  --border-subtle: rgba(42, 25, 17, 0.13);
  --border-strong: rgba(42, 25, 17, 0.28);
  --shadow-sm: 0 4px 14px rgba(42, 25, 17, 0.06);
  --shadow-md: 0 10px 28px rgba(42, 25, 17, 0.08);
  --shadow-lg: 0 16px 36px rgba(42, 25, 17, 0.13);
  --success-green: #246a46;
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 22px;
  --radius-arch: 999px 999px 18px 18px;
  --font-display: "Playfair Display", "Cormorant Garamond", "Georgia", serif;
  --font-sans: "Plus Jakarta Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --max-width: 1120px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-family: var(--font-sans);
  color: var(--ink-primary);
  background-color: var(--bg-page);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input {
  font-family: inherit;
}

img,
svg {
  display: block;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* ==========================================================================
   Header & Navigation
   ========================================================================== */

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background-color: rgba(255, 253, 249, 0.92);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border-subtle);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-height: 74px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  font-family: var(--font-display);
  font-size: 1.48rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: var(--ink-primary);
  flex-shrink: 0;
}

.brand-icon {
  width: 36px;
  height: 36px;
  flex-shrink: 0;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-links a {
  position: relative;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--ink-secondary);
  padding: 8px 2px;
  transition: color 0.18s ease;
}

.nav-links a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 2px;
  height: 2px;
  border-radius: 2px;
  background-color: var(--accent-caramel);
  transform: scaleX(0);
  transition: transform 0.2s ease;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--ink-primary);
}

.nav-links a.active::after,
.nav-links a:hover::after {
  transform: scaleX(1);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.icon-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: 1px solid transparent;
  border-radius: 50%;
  background: transparent;
  color: var(--ink-primary);
  cursor: pointer;
  transition: background-color 0.18s ease, border-color 0.18s ease, transform 0.12s ease;
}

.icon-btn:hover {
  background-color: var(--bg-cream);
  border-color: var(--border-subtle);
}

.icon-btn svg {
  width: 21px;
  height: 21px;
}

.cart-badge {
  position: absolute;
  top: 0;
  right: -2px;
  min-width: 19px;
  height: 19px;
  padding: 0 5px;
  border-radius: 999px;
  background-color: var(--accent-berry);
  color: #fff;
  border: 2px solid #fff;
  font-size: 0.7rem;
  font-weight: 700;
  line-height: 15px;
  text-align: center;
}

.cart-badge.is-empty {
  display: none;
}

.menu-toggle {
  display: none;
}

.mobile-nav {
  display: none;
  border-top: 1px solid var(--border-subtle);
  background-color: var(--bg-surface);
  padding: 12px 24px 18px;
}

.mobile-nav.is-open {
  display: block;
}

.mobile-nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mobile-nav-list a {
  display: block;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  color: var(--ink-secondary);
}

.mobile-nav-list a:hover,
.mobile-nav-list a.active {
  background-color: var(--bg-cream);
  color: var(--ink-primary);
}

/* ==========================================================================
   Main Layout & Footer
   ========================================================================== */

main {
  flex: 1;
  padding: 32px 0 60px;
}

.site-footer {
  border-top: 1px solid var(--border-subtle);
  background-color: var(--bg-surface);
  padding: 20px 0;
  font-size: 0.88rem;
  color: var(--ink-muted);
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.footer-tagline {
  font-family: var(--font-display);
  font-style: italic;
  color: var(--ink-secondary);
}

/* ==========================================================================
   Buttons
   ========================================================================== */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 26px;
  font-size: 0.94rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  border-radius: 999px;
  border: 1.5px solid var(--accent-espresso);
  cursor: pointer;
  transition: transform 0.15s ease, background-color 0.18s ease, box-shadow 0.18s ease, color 0.18s ease;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

.btn-primary {
  background-color: var(--accent-espresso);
  color: #fff;
  box-shadow: 0 6px 16px rgba(59, 34, 22, 0.2);
}

.btn-primary:hover {
  background-color: var(--accent-espresso-hover);
  box-shadow: 0 8px 20px rgba(59, 34, 22, 0.28);
}

.btn-secondary {
  background-color: var(--bg-surface);
  color: var(--ink-primary);
}

.btn-secondary:hover {
  background-color: var(--bg-cream);
}

/* ==========================================================================
   Webpage 1 — Home Page
   ========================================================================== */

.hero-box {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  align-items: stretch;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-subtle);
