.cake-art {
  width: 100%;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background-color: var(--bg-cream);
}

.cake-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.35s ease;
}

.cake-card:hover .cake-art img {
  transform: scale(1.05);
}

.cake-card-body {
  padding: 18px 20px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  flex: 1;
}

.cake-name {
  margin: 0 0 6px;
  font-family: var(--font-display);
  font-size: 1.22rem;
  font-weight: 700;
  color: var(--ink-primary);
}

.cake-price {
  margin: 0 0 16px;
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--accent-caramel);
}

.cake-price-label {
  display: none;
}

.add-cart-btn {
  width: 100%;
  margin-top: auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 11px 16px;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink-primary);
  background-color: var(--bg-cream);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  cursor: pointer;
  transition: background-color 0.18s ease, border-color 0.18s ease, color 0.18s ease;
}

.add-cart-btn:hover {
  background-color: var(--accent-espresso);
  border-color: var(--accent-espresso);
  color: #fff;
}

.add-cart-btn svg {
  width: 17px;
  height: 17px;
  flex-shrink: 0;
}

/* ==========================================================================
   Toast Notification (State 2 — Item Added)
   ========================================================================== */

.toast {
  position: fixed;
  right: 22px;
  bottom: 24px;
  z-index: 100;
  min-width: 270px;
  max-width: 350px;
  padding: 14px 18px;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-strong);
  border-left: 4px solid var(--success-green);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  transform: translateY(12px);
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.toast.is-visible {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

.toast-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 3px;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--success-green);
}

.toast-message {
  margin: 0;
  font-size: 0.88rem;
  color: var(--ink-secondary);
}

/* ==========================================================================
   Responsive Breakpoints (Desktop -> Tablet -> Mobile Prototype)
   ========================================================================== */

@media (max-width: 900px) {
  .hero-box {
    grid-template-columns: 1fr;
  }

  .hero-media {
    order: -1;
    min-height: 240px;
    max-height: 280px;
  }

  .hero-content {
    padding: 32px 28px;
  }

  .arch-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cakes-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .container {
    padding: 0 18px;
  }

  .nav-links,
  .header-search-btn {
    display: none;
  }

  .menu-toggle {
    display: inline-flex;
  }

  main {
    padding: 20px 0 40px;
  }

  .hero-box {
    margin-bottom: 30px;
  }

  .hero-media {
    min-height: 200px;
    max-height: 220px;
  }

  .hero-content {
    padding: 22px 18px;
  }

  .hero-title {
    font-size: 1.72rem;
  }

  .hero-actions {
    gap: 10px;
  }

  .hero-actions .btn {
    flex: 1 1 auto;
    padding: 10px 14px;
    font-size: 0.9rem;
  }

  /* Mobile View: Shop by Category becomes stacked horizontal photo-left cards */
  .category-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .category-grid .arch-card {
    flex-direction: row;
    align-items: center;
    justify-content: flex-start;
    border-radius: var(--radius-md);
    padding: 10px 14px;
    gap: 14px;
  }

  .category-grid .arch-card-media {
    width: 64px;
    height: 64px;
    aspect-ratio: 1 / 1;
    border-radius: 10px;
    margin-bottom: 0;
    flex-shrink: 0;
  }

  .category-grid .arch-card-text {
    text-align: left;
    padding: 0;
  }

  .arch-grid {
    gap: 14px;
  }

  .arch-card {
    padding: 8px 8px 14px;
  }

  /* Vertical Prototype State 1: Cakes page mobile stacked rows with divider */
  .cakes-grid {
    grid-template-columns: 1fr;
    gap: 0;
    background-color: var(--bg-surface);
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-sm);
    overflow: hidden;
  }

  .cake-card {
    border: none;
    border-bottom: 1px solid var(--border-subtle);
    border-radius: 0;
    box-shadow: none;
    padding: 16px;
  }

  .cake-card:hover {
    transform: none;
    box-shadow: none;
  }

  .cake-card:last-child {
    border-bottom: none;
  }

  .cake-card-top {
    flex-direction: row;
    align-items: center;
    gap: 14px;
    margin-bottom: 12px;
  }

  .cake-art {
    width: 78px;
    height: 78px;
    aspect-ratio: 1 / 1;
    border-radius: 12px;
    flex-shrink: 0;
  }

  .cake-card-body {
    padding: 0;
    align-items: stretch;
    text-align: left;
  }

  .cake-name {
    font-size: 1.2rem;
    margin: 0;
  }

  .cake-price {
    margin: 0 0 12px;
    font-size: 0.98rem;
  }

  .cake-price-label {
    display: inline;
    font-weight: 500;
    color: var(--ink-muted);
    margin-right: 4px;
  }

  .menu-row {
    padding: 12px 14px;
    gap: 12px;
  }

  .menu-thumb {
    width: 58px;
    height: 58px;
  }

  .toast {
    left: 16px;
    right: 16px;
    bottom: 18px;
    max-width: none;
  }
}
